/* Beginner-first workflow, with the full SVG editor available behind one switch. */
class EasyStudio extends StudioCanvas {
 constructor(){super();this.mode='basic';try{this.mode=localStorage.getItem('paperplane-editor-mode')==='advanced'?'advanced':'basic';}catch{}this.installEasyUI();this.easyReady=true;this.applyMode();
   if(state.headline&&state.layoutRevision!==3){const previous=StudioStorage.pack(state);StudioStorage.put({id:'before-refresh-'+Date.now(),name:'Previous layout (before refresh)',updated:Date.now(),category:state.category,data:previous}).catch(()=>{try{localStorage.setItem('paperplane-previous-layout',JSON.stringify(previous));}catch{}});state.scenes={};}
   state.layoutRevision=3;
 }
 installEasyUI(){
   document.querySelector('#editorPane .section-heading h2').textContent='Make it yours.';
   document.querySelector('#editorPane .section-heading p').textContent='Add your words, choose a look, and download your poster.';
   document.querySelector('#editorPane .section-heading').insertAdjacentHTML('afterend',`<div class="editor-navigation"><div class="editor-mode" aria-label="Editor mode"><button data-easy="mode-basic">Simple editor</button><button data-easy="mode-advanced">Advanced editor</button></div><span id="modeHint">We’ll take care of the layout.</span></div>`);
   document.querySelector('.controls').id='editorFields';document.querySelector('.canvas-area').id='editorPreview';document.querySelector('.looks').id='editorDesigns';
   document.querySelector('.editor-navigation').insertAdjacentHTML('afterend','<nav id="mobileEditorNav" aria-label="Editor sections"><a href="#editorFields">Your words</a><a href="#editorPreview">Preview</a><a href="#editorDesigns">Designs</a></nav>');
   document.querySelector('.canvas-toolbar').insertAdjacentHTML('beforebegin','<div id="basicTools"><div><button data-action="undo" title="Undo last change">↶ Undo</button><button data-action="redo" title="Redo last change">↷ Redo</button></div><div><button data-easy="picture">Change picture</button><button data-easy="reset">Reset layout</button></div></div>');
   const details=document.querySelector('#detailsTab');details.insertAdjacentHTML('afterbegin','<div class="panel-intro"><h3>Your poster details</h3><p>Your words will wrap and fit automatically.</p></div>');
   for(const [id,label]of Object.entries({kicker:'Small heading (optional)',headline:'Main message',subtitle:'More information',price:'Price or special offer',footer:'Date, place, or contact details',paper:'Poster size',font:'Text style'})){const input=document.querySelector('#'+id);const parent=input.closest('label');const text=[...parent.childNodes].find(n=>n.nodeType===Node.TEXT_NODE);if(text)text.textContent=label;}
   document.querySelector('#headline').placeholder='What should people notice first?';document.querySelector('#subtitle').placeholder='A few helpful details…';document.querySelector('#footer').placeholder='Where, when, or how to get in touch';
   const heading=document.querySelector('#headline').closest('label');details.querySelector('.panel-intro').after(heading);
   const row=document.querySelector('#price').closest('.two-col'),offer=document.createElement('details');offer.id='optionalOffer';offer.innerHTML='<summary>Price or offer (optional)</summary>';row.before(offer);offer.append(row);
   document.querySelectorAll('[data-tab]').forEach(b=>b.textContent={details:'Words & colors',artwork:'Pictures & graphics',object:'Selected item',layers:'Layers'}[b.dataset.tab]);
   document.querySelector('.look-title').innerHTML='CHOOSE A DESIGN <span>12</span>';
   document.querySelector('.model-switch').insertAdjacentHTML('afterend','<p class="design-help">Try another look. Your words stay with you.</p>');
   document.querySelector('#brief').maxLength=1500;
   document.querySelector('#briefForm').insertAdjacentHTML('afterend','<div id="promptSuggestions" class="prompt-suggestions" role="region" aria-label="Suggested poster types" hidden></div><p id="promptHelp" class="prompt-help">Try a subject, an offer, and the details you want to include.</p>');
   let timer;document.querySelector('#brief').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>this.suggest(),120);});
   document.body.insertAdjacentHTML('beforeend','<dialog id="easyExport" class="studio-dialog"><div class="dialog-heading"><h2>Download your poster</h2><button data-easy="close-export" aria-label="Close download options">×</button></div><p>Choose a format. Your poster will download to your device.</p><label class="easy-field">File type<select id="easyFormat"><option value="png">PNG image • ideal for printing</option><option value="jpeg">JPG image • smaller file</option><option value="svg">SVG • scalable design file</option></select></label><label class="easy-field">Image quality<select id="easyQuality"><option value="300">High quality • printing</option><option value="150">Medium • sharing</option><option value="72">Small • screen use</option></select></label><div class="easy-download-actions"><button class="primary" data-easy="download">Download poster ↗</button><button data-easy="print">Print or save as PDF</button></div></dialog>');
   document.querySelector('#easyFormat').addEventListener('change',e=>document.querySelector('#easyQuality').closest('label').hidden=e.target.value==='svg');
   document.querySelector('[data-command="projects"]').textContent='Save / open';
 }
 applyMode(){document.body.dataset.editorMode=this.mode;document.querySelectorAll('[data-easy^="mode-"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.easy===`mode-${this.mode}`)));document.querySelector('#modeHint').textContent=this.mode==='basic'?'We’ll take care of the layout.':'Select, move, resize, and fine-tune every element.';document.querySelector('#optionalOffer').open=this.mode==='advanced'||Boolean(state.price);if(this.mode==='basic'){this.selected=null;this.selection.clear();this.openTab('details');}try{localStorage.setItem('paperplane-editor-mode',this.mode);}catch{}}
 suggest(){const text=document.querySelector('#brief').value,box=document.querySelector('#promptSuggestions');if(text.trim().length<3){box.hidden=true;document.querySelector('#promptHelp').textContent='Try a subject, an offer, and the details you want to include.';return;}const suggestions=PromptEngine.suggestions(text),fields=PromptEngine.extract(text);box.replaceChildren();for(const suggestion of suggestions){const button=document.createElement('button');button.type='button';button.dataset.promptCategory=suggestion.id;const label=document.createElement('strong');label.textContent=suggestion.label;const small=document.createElement('span');small.textContent='Explore six ideas ↗';button.append(label,small);box.append(button);}box.hidden=!suggestions.length;const found=[fields.price?`Price: ${fields.currency||''}${fields.price}`:'',fields.date?`Date: ${fields.date}`:'',fields.venue?`Place: ${fields.venue}`:'',fields.email?'Email found':'',fields.phone?'Phone found':''].filter(Boolean);document.querySelector('#promptHelp').textContent=found.length?found.join(' · '):suggestions.length?'Choose a suggested type, or keep describing your idea.':'Keep describing your idea, or choose a starting point below.';}
 applyPromptDetails(){const fields=PromptEngine.extract(state.brief);state.brief=fields.text;if(fields.title)state.headline=fields.title;if(fields.price!==undefined){state.price=fields.price;state.currency=fields.currency||'';}if(fields.discount&&state.category==='sale'&&!fields.price)state.price=fields.discount+' OFF';let parts=state.footer?[state.footer]:[];if(state.category==='lost'&&(fields.phone||fields.email))parts=[];for(const value of [fields.date,fields.venue,fields.phone,fields.email,fields.website].filter(Boolean))if(!parts.join(' ').toLowerCase().includes(value.toLowerCase()))parts.push(value);state.footer=parts.join(' • ');state.layoutRevision=3;}
 render(){super.render();if(this.easyReady){document.querySelector('#download').textContent='Download ↗';document.querySelector('#modeHint').textContent=this.mode==='basic'?'We’ll take care of the layout.':'Select, move, resize, and fine-tune every element.';if(state.price)document.querySelector('#optionalOffer').open=true;}}
 selectionSvg(){return this.mode==='basic'?'':super.selectionSvg();}
 contain(n){if(!n||n.type!=='text')return;const{width,height}=this.dimensions();const pad=28;if(n.width>width-pad*2)n.width=width-pad*2;if(n.height>height-pad*2)n.height=height-pad*2;n.x=Math.max(pad,Math.min(width-pad-n.width,n.x));n.y=Math.max(pad,Math.min(height-pad-n.height,n.y));}
 updateBinding(key){super.updateBinding(key);if(this.mode==='basic'){for(const doc of Object.values(state.scenes||{}))for(const n of doc.nodes)this.contain(n);}}
 input(e){const field=e.target;if(['headline','subtitle','kicker','footer','price','currency'].includes(field.id))field.value=TextLayout.clean(field.value,field.id==='subtitle'?500:field.id==='headline'?160:200,false);if(field.dataset.prop==='text')field.value=TextLayout.clean(field.value,1500,false);super.input(e);if(this.mode==='basic'&&field.id==='font'){for(const doc of Object.values(state.scenes||{}))for(const n of doc.nodes)this.contain(n);this.paint();save();}}
 pointerDown(e){if(this.mode!=='basic'){super.pointerDown(e);return;}const id=e.target.closest('[data-node]')?.dataset.node;const n=this.doc().nodes.find(n=>n.id===id);if(n?.binding){e.preventDefault();const field=document.querySelector('#'+n.binding);const disclosure=field?.closest('details');if(disclosure)disclosure.open=true;field?.focus();field?.scrollIntoView({block:'nearest',behavior:'smooth'});}else if(n?.type==='photo'){e.preventDefault();this.changePicture();}}
 changePicture(){const photo=this.doc().nodes.find(n=>n.type==='photo'&&!n.hidden);if(photo){this.selected=photo.id;this.selection=new Set([photo.id]);this.replacingPhoto=true;}else{this.selected=null;this.selection.clear();this.replacingPhoto=false;}document.querySelector('#upload').click();}
 resetLayout(){this.checkpoint();const photo=this.doc().nodes.find(n=>n.type==='photo');const href=photo?this.parse(photo.source).querySelector('image')?.getAttribute('href'):null;if(href)state.photo=href;state.scenes[state.look]=this.seed(state.look);this.selected=null;this.selection.clear();this.changed();toast('Layout refreshed. Your words and picture are kept. Undo is available.');}
 click(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.easy){e.preventDefault();e.stopImmediatePropagation();const action=b.dataset.easy;if(action==='mode-basic'||action==='mode-advanced'){this.mode=action==='mode-basic'?'basic':'advanced';this.applyMode();this.changed();}else if(action==='picture')this.changePicture();else if(action==='reset')this.resetLayout();else if(action==='close-export')document.querySelector('#easyExport').close();else if(action==='download'){document.querySelector('#exportType').value=document.querySelector('#easyFormat').value;document.querySelector('#exportQuality').value=document.querySelector('#easyQuality').value;document.querySelector('#easyExport').close();this.exportImage();}else if(action==='print'){document.querySelector('#easyExport').close();this.print();}return;}if(b.dataset.promptCategory){e.preventDefault();e.stopImmediatePropagation();state.brief=PromptEngine.clean(document.querySelector('#brief').value);document.querySelector('#brief').value=state.brief;document.querySelector('#promptSuggestions').hidden=true;setCategory(b.dataset.promptCategory,true);return;}if(b.id==='download'&&this.mode==='basic'){e.preventDefault();e.stopImmediatePropagation();document.querySelector('#easyExport').showModal();return;}super.click(e);}
 keydown(e){if(this.mode==='basic'&&!e.target.closest('input,textarea,select')&&(e.key==='Delete'||e.key==='Backspace'||(e.ctrlKey||e.metaKey)&&['a','d','g'].includes(e.key.toLowerCase())))return;super.keydown(e);}
}
